\[\begin{align}
\frac{1}{Z} = \frac{1}{Z_0 + j\omega\delta L} + \frac{1}{\frac{1}{j\omega\delta C}} = \frac{1}{Z_0}
\tag{A.8}\\
Z_0^2 + j\,\omega\,\delta L\,Z_0 - \delta L/\delta C = 0
\tag{A.9}
\end{align}\]

\[\begin{align}
L_x\,\Delta x\, I &= \frac{\mu\mu_0}{2\pi} I \int_a^d \left(\frac{1}{r} + \frac{1}{2d - r}\right) dr\,\Delta x
\tag{B.1}\\
L_x &= \frac{\mu\mu_0}{2\pi}\ln\left(\frac{2d}{a} - 1\right) \approx \frac{\mu\mu_0}{2\pi}\ln\frac{2d}{a}
\tag{B.2}
\end{align}\]

\[\begin{align}
\varphi &= \frac{\Delta q}{\Delta x}\frac{1}{2\pi\varepsilon_\mathrm{r}\varepsilon_0}\int_a^d \left(\frac{1}{r} + \frac{1}{2d - r}\right) dr = \frac{\Delta q}{\Delta x}\frac{\ln(2d/a)}{2\pi\varepsilon_\mathrm{r}\varepsilon_0}
\tag{B.3}\\
C_x &= \frac{\Delta q}{\Delta x}\frac{1}{\varphi} \approx \frac{2\pi\varepsilon_\mathrm{r}\varepsilon_0}{\ln(2d/a)}
\tag{B.4}
\end{align}\]

\[\begin{equation}
Z_\mathrm{tot} = \left(\frac{1}{\frac{1}{j\,\omega\,C_0}} + \frac{1}{R_\mathrm{SET}}\right)^{-1} + j\,\omega L_0 = \frac{R_\mathrm{SET}}{1 + j\,\omega C_0\,R_\mathrm{SET}} + j\,\omega\,L_0 = \frac{R_\mathrm{SET} + j\,\sqrt{L_0/C_0}}{1 + R_\mathrm{SET}^2C_0/L_0}
\tag{E.6}
\end{equation}\]
